# 毕业设计 Step14: 结构化日志 + 健康检查
import json
import time
from datetime import datetime


def log_json(level: str, event: str, **fields):
    """结构化日志: 每行一个JSON, 日志系统可直接索引。"""
    record = {"ts": datetime.now().isoformat(timespec="milliseconds"),
              "level": level, "event": event, **fields}
    print(json.dumps(record, ensure_ascii=False))


class RequestLogger:
    """记录每个请求的黄金字段: 方法/路径/状态码/耗时。"""

    def __init__(self):
        self.count = 0
        self.total_ms = 0.0

    def log_request(self, method: str, path: str, status: int, start: float):
        ms = (time.time() - start) * 1000
        self.count += 1
        self.total_ms += ms
        log_json("INFO", "http_request", method=method, path=path,
                 status=status, latency_ms=round(ms, 1))

    @property
    def avg_ms(self) -> float:
        return self.total_ms / self.count if self.count else 0.0


def liveness() -> dict:
    """活着没: 进程能响应就True。"""
    return {"status": "alive"}


def readiness(deps: dict) -> dict:
    """能接客没: 所有依赖就绪才ready。"""
    checks = {name: ok for name, ok in deps.items()}
    return {"status": "ready" if all(checks.values()) else "not_ready", "checks": checks}


# 模拟两个请求
rl = RequestLogger()
for path, ms_sleep in [("/questions", 0.01), ("/documents", 0.02)]:
    t = time.time()
    time.sleep(ms_sleep)
    rl.log_request("POST", path, 200, t)
log_json("INFO", "stats", total_requests=rl.count, avg_ms=round(rl.avg_ms, 1))
print(liveness())
print(readiness({"vector_db": True, "llm_api": True}))

